<?php /** @var array<string,mixed> $p */ /** @var ?array<string,int> $balance */ /** @var bool $canDecide */ /** @var list<array<string,mixed>> $referrals */ use Vertex\Core\View; ?>
<div class="page-head"><div><p class="eyebrow">Partner</p><h1><?= e($p['reference']) ?> · <?= e($p['name']) ?></h1></div><a class="btn btn-ghost" href="/referrals/partners">&larr; Partners</a></div>
<div class="panel"><div class="detail-grid"><div><span class="muted">Status</span><br><span class="badge badge-ps-<?= e($p['status']) ?>"><?= e(ucfirst($p['status'])) ?></span></div><div><span class="muted">Email</span><br><?= e($p['email']) ?></div>
    <div><span class="muted">Payout details</span><br><?= $p['payout_details_hint'] ? e($p['payout_details_hint']) : 'none' ?></div><div><span class="muted">Terms</span><br><?= $p['terms_version'] ? 'v' . e($p['terms_version']) : '—' ?></div></div>
    <?php if ($balance) : ?><div class="stat-grid"><div class="stat"><span class="stat-n"><?= e(money($balance['available'])) ?></span><span class="stat-l">Payable balance</span></div><div class="stat"><span class="stat-n"><?= e(money($balance['reserved'])) ?></span><span class="stat-l">Reserved</span></div>
        <div class="stat"><span class="stat-n"><?= e(money($balance['paid'])) ?></span><span class="stat-l">Paid</span></div><div class="stat"><span class="stat-n"><?= e(money($balance['eligible_for_review'] + $balance['approved'])) ?></span><span class="stat-l">Pending</span></div></div><?php endif; ?></div>
<?php if ($canDecide) : ?><div class="panel"><h2><?= $p['status'] === 'active' ? 'Suspend' : 'Reactivate' ?></h2>
    <form method="post" action="/referrals/partners/<?= e($p['public_id']) ?>" class="form-grid" data-confirm="Change this partner's status?"><?= csrf_field() ?>
        <div class="field"><label for="sr">Reason (required)</label><input id="sr" name="reason" required maxlength="255"></div>
        <div class="form-actions"><button class="btn btn-ghost btn-sm" type="submit" name="action" value="<?= $p['status'] === 'active' ? 'suspend' : 'reactivate' ?>"><?= $p['status'] === 'active' ? 'Suspend partner' : 'Reactivate partner' ?></button></div></form></div><?php endif; ?>
<div class="panel"><h2>Recent referrals</h2><ul class="plain-list"><?php foreach ($referrals as $r) : ?><li><a href="/referrals/<?= e($r['public_id']) ?>"><?= e($r['reference']) ?></a> · <?= e($r['prospect_name']) ?> · <?= View::partial('pbadge', ['kind' => 'referral', 's' => $r['status']]) ?></li><?php endforeach; ?></ul></div>
